mapper.select:
SELECT fruit_tree.`id`,fruit_tree.`type`,fruit_tree.`count_num`,fruit_tree.`ripe_num`,fruit_tree.`img`,fruit_tree.`area_id`
FROM fruit_tree,area_info,fruit_type
WHERE fruit_tree.`area_id` = area_info.`id` AND fruit_tree.`type` = fruit_type.`id` AND fruit_tree.`id` = #{id}

SELECT fruit_tree.`id`,fruit_type.`type`,fruit_type.id AS type_id,fruit_tree.`count_num`,fruit_tree.`ripe_num`,fruit_tree.`img`,area_info.`name`,fruit_tree.`area_id`
FROM fruit_tree,area_info,fruit_type
WHERE fruit_tree.`area_id` = area_info.`id` AND fruit_tree.`type` = fruit_type.`id` AND area_id = #{areaId}

SELECT *
FROM fruit_emp
WHERE emp_id = #{userId} AND tree_id = #{treeId}

SELECT orchard.name
FROM orchard
WHERE orchard.id = #{orchardId}

SELECT COUNT(fruit_tree.id)
FROM fruit_tree, area_info
WHERE fruit_tree.type = #{typeId}
  AND area_info.orchard_id = #{orchardId}
  AND area_info.id = fruit_tree.area_id

SELECT SUM(fruit_tree.ripe_num)
FROM fruit.fruit_tree, area_info
WHERE area_info.orchard_id = #{orchardId}
  AND area_info.id = #{areaId}
  AND area_info.id = fruit_tree.area_id

SELECT SUM(fruit_tree.count_num)
FROM fruit.fruit_tree, area_info
WHERE area_info.orchard_id = #{orchardId}
  AND area_info.id = #{areaId}
  AND area_info.id = fruit_tree.area_id

SELECT fruit_tree.*
FROM fruit.fruit_tree
WHERE fruit_tree.id = #{treeId}
